\STATE Initialize discrete actor $\pi_{	heta_v^d}$, $\pi_{	heta_v^d}^{old}$, discrete critic $Q_{\omega_v^d}$, $Q_{ ar{\omega}_v^d}$, continuous actor $\pi_{	heta_v^c}$, $\pi_{	heta_v^c}^{old}$, continuous critic $Q_{\omega_v^c}$, $Q_{{\overline{\omega}}_v^c}$;\STATE Initialize environment $Env$, Initialize replay buffer $D$;\FOR {Episode $1,2,\dots,E$}\FOR{Time slot $t=1,2,\dots,T$}\STATE Add predicted workload into the observation of each agent $v$;\STATE Each agent $v$ gets $a_v^t = \{ a_v^d(t),a_v^c(t)\}$ according to $o_v^t$ by discrete actor $\pi_{	heta_v^d}^{old}$ and continuous actor $\pi_{	heta_v^c}^{old}$ respectively;\STATE Get next state $o^{t+1}$ and reward $r^t$;\ENDFOR\STATE Each agent $v$ gets a trajectory $	au_v=\{o_v^t,a_v^t,r_v^t\}_{t=1}^{T}$;\STATE Compute ${\{\hat{Q}_v^d[o^t,a^d(t)]\}}_{t=1}^{T}$ according to Eq.(ef{hatqd});\STATE Compute ${\{\hat{Q}_v^c[o^t,a^c(t)]\}}_{t=1}^{T}$ according to Eq.(ef{hatqc});\STATE Compute ${\{A_v^d[o^t,a^d(t)]\}}_{t=1}^{T}$ according to Eq.(ef{advd});\STATE Compute ${\{A_v^c[o^t,a^c(t)]\}}_{t=1}^{T}$ according to Eq.(ef{advc});\STATE Store ${\{o,a^d,\{\hat{Q}^d(o,a^d)\},\{A^d(o,a^d)\},r\}}$ and ${\{o,a^c,\{\hat{Q}^c(o,a^c)\},\{A^c(o,a^c)\},r\}}$ into replay buffer $D$;\FOR{epoch k=1,2,...,K}\STATE Shuffle the data in the buffer $D$\FOR{j=0,1,2,...,{$ rac{T}{G}$}-1}\STATE Sample $G$ mini-batch of data from buffer $D$\FOR{v=1,2,...,V}\STATE $\Delta	heta_v^d= rac{1}{G}\sum_{i=1}^G\{{
abla}_{	heta_v^d}F( eta_{	heta_v^d}^i,A_v^d[o_i,a_i])\}$\STATE $\Delta	heta_v^c= rac{1}{G}\sum_{i=1}^G\{{
abla}_{	heta_v^c}F( eta_{	heta_v^c}^i,A_v^c[o_i,a_i])\}$\STATE $\Delta\omega_v^d= rac{1}{G}\sum_{i=1}^G\{{
abla}_{\omega_v^d}[\hat{Q}_v(o_i,a_i)-Q_{\omega_v^d}(o_i,a_i)]^2\}$\STATE $\Delta\omega_v^c= rac{1}{G}\sum_{i=1}^G\{{
abla}_{\omega_v^c}[\hat{Q}_v(o_i,a_i)-Q_{\omega_v^c}(o_i,a_i)]^2\}$\ENDFOR\STATE Update $	heta_v^d$, $	heta_v^c$ using $\Delta	heta_v^d$, $\Delta	heta_v^c$;\STATE Update $\omega_v^d$, $\omega_v^c$ using $\Delta\omega_v^d$, $\Delta\omega_v^c$;\ENDFOR\ENDFOR\STATE Update $	heta_v^{d(old)}\xleftarrow{} 	heta_v^d $, $	heta_v^{c(old)}\xleftarrow{} 	heta_v^c $;\STATE Update $\overline{\omega}_v^d\xleftarrow{}\omega_v^d$, $\overline{\omega}_v^c\xleftarrow{}\omega_v^c$.\ENDFOR
